//Input value 6 HE_StateControl(EXT_StateData:=EXT_Engineering.StateCfg_6, Inp_Visibility:=Inp_StateSuffix[6]<>'', Inp_State:=Inp_StateState[6], Inp_Desc:=Inp_StateSuffix[6], Sts_Quality:=EXT_General.Sts_Quality, Sts_ActionState:=Wrk_ActionState, Sts_AlarmSuffix=>Wrk_AlarmData[5].Alm_Suffix, Sts_AlarmState=>Wrk_AlarmData[5].Alm_State, Sts_AlarmPriority=>Wrk_AlarmData[5].Alm_Priority);
//Input value 7 HE_StateControl(EXT_StateData:=EXT_Engineering.StateCfg_7, Inp_Visibility:=Inp_StateSuffix[7]<>'', Inp_State:=Inp_StateState[7], Inp_Desc:=Inp_StateSuffix[7], Sts_Quality:=EXT_General.Sts_Quality, Sts_ActionState:=Wrk_ActionState, Sts_AlarmSuffix=>Wrk_AlarmData[6].Alm_Suffix, Sts_AlarmState=>Wrk_AlarmData[6].Alm_State, Sts_AlarmPriority=>Wrk_AlarmData[6].Alm_Priority);
