//Input value 12 HE_StateControl(EXT_StateData:=EXT_Engineering.StateCfg_12, Inp_Visibility:=Inp_StateSuffix[12]<>'', Inp_State:=Inp_StateState[12], Inp_Desc:=Inp_StateSuffix[12], Sts_Quality:=EXT_General.Sts_Quality, Sts_ActionState:=Wrk_ActionState, Sts_AlarmSuffix=>Wrk_AlarmData[11].Alm_Suffix, Sts_AlarmState=>Wrk_AlarmData[11].Alm_State, Sts_AlarmPriority=>Wrk_AlarmData[11].Alm_Priority);
(************************************************************************* * EXCECUTING ALARM BLOCK *************************************************************************)
FB_AlarmGeneral(ENS:=TRUE, Ext_Alarm:=Ext_Alarm, Int_Alarm:=Int_Alarm, Inp_AlarmData:=Wrk_AlarmData, Inp_LocationData:=EXT_General.LocationIndex, Inp_AlarmSupress:=Inp_AlmSuppress, Inp_AlmSuppressDesc:=Inp_AlmSuppressDesc, Inp_Connected_Cabinet:=Ext_General.Connected_ControlCabinet, Inp_Connected_Controller:=Ext_General.Controlled_FromController, Inp_Process_TAG:=Ext_General.Process_TAG, Inp_Process_Desc:=Ext_General.Process_Desc, Inp_Process_Value:='', //Not relevant Out_AlarmToken=>Wrk_AlarmToken, Out_AlarmTriggered=>Wrk_AlarmTriggered);
(************************************************************************* * OUTPUT DATA *************************************************************************)
//BLOCK OUTPUT //------------------
Sts_AlarmTriggered:= Wrk_AlarmTriggered; Sts_AlarmToken:= Wrk_AlarmToken;
